// @vegastack terminal@0.7.2 sha256-DDmHUtlBypUeFxmDMtUM5jqZ++fz1E4jrEiy4ehgMMU=

import * as React from "react";
import { cn } from "@vegastack/design";
// `CopyButton` is owned by the sibling CopyButton component; shadcn rewrites this alias on
// `add`, and vitest/tsconfig map `@/components/ui/*` → `registry/ui/*`.
import { CopyButton } from "@/components/ui/copy-button";
import { TerminalBody } from "@/components/ui/terminal-body";

export interface TerminalLine {
  /** Command text, rendered after the prompt glyph. */
  command?: string;
  /** Non-command output/comment line — no prompt glyph, dimmed. */
  output?: string;
}

/** Props accepted by `Terminal`. */
export interface TerminalProps extends Omit<
  React.ComponentPropsWithRef<"div">,
  "children" | "title"
> {
  /**
   * The lines to render, top to bottom. A plain string is shorthand for
   * `{ command: string }`. Content is fully caller-supplied (no timestamps,
   * no randomness) — deterministic by construction, so it's VRT-stable.
   */
  lines: (string | TerminalLine)[];
  /**
   * The prompt glyph shown before each command line — the sanctioned
   * "terminal prompt glyph" `--brand` marker role (audit 17-brand-direction
   * §Color & surface).
   * @default '$'
   */
  prompt?: string;
  /** Small mono uppercase label in the header bar. @default 'Terminal' */
  title?: React.ReactNode;
  /**
   * Value copied by the trailing `CopyButton`. Defaults to every `command`
   * line (not `output` lines) joined with newlines.
   * @default derived from command lines
   */
  copyValue?: string;
  /**
   * Accessible name for the scrollable command pane, which is a keyboard focus
   * stop while it overflows. Overrides the default, which names the pane from the
   * visible `title`. Mirrors `ScrollArea`: the label is intercepted here and
   * applied to the focusable element, not to the outer block.
   * @default derived from `title`
   */
  "aria-label"?: string;
  /**
   * Id of an element naming the scrollable command pane. Takes precedence over
   * the visible `title`; ignored when `aria-label` is set.
   * @default the visible title element
   */
  "aria-labelledby"?: string;
}

function normalizeLine(line: string | TerminalLine): TerminalLine {
  return typeof line === "string" ? { command: line } : line;
}

/**
 * `Terminal` (a.k.a. CommandBlock) — a dark mono command block: a title bar
 * over command/output lines, each command prefixed with a `--brand` phosphor
 * prompt glyph, plus a composed trailing {@link CopyButton}. The command pane
 * scrolls independently, so the copy action remains visible at the inline end —
 * which makes it a keyboard focus stop **whenever it actually overflows**, named
 * from the visible `title` and exposed as a `group` (override with
 * `aria-label`/`aria-labelledby`). A pane whose commands fit adds no tab stop.
 * Self-scopes to the
 * marketing dark ground (`.vs-marketing`) so it reads correctly even embedded
 * in a light-theme docs page (e.g. an install snippet) — no `MarketingSurface`
 * wrapper required, though nesting one is harmless (values are identical).
 *
 * @example
 * <Terminal
 *   title="Install"
 *   lines={[
 *     'pnpm dlx shadcn@latest add @vegastack/button',
 *     { output: '✓ Installed 1 component' },
 *   ]}
 * />
 */
export function Terminal({
  lines,
  prompt = "$",
  title = "Terminal",
  copyValue,
  className,
  ref,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: TerminalProps) {
  // `useId` is one of the few React hooks that resolves under the `react-server`
  // condition, so naming the pane costs this component nothing: it stays
  // server-safe with no `'use client'` directive.
  const titleId = React.useId();
  const normalized = lines.map(normalizeLine);
  const defaultCopyValue = normalized
    .filter((line) => line.command !== undefined)
    .map((line) => line.command)
    .join("\n");

  return (
    <div
      ref={ref}
      data-slot="terminal"
      className={cn(
        "vs-marketing overflow-hidden rounded-(--radius-sharp) border border-border bg-card",
        className,
      )}
      {...props}
    >
      <div
        data-slot="terminal-header"
        className="flex items-center border-b border-border px-3 py-2"
      >
        <span
          id={titleId}
          className="font-mono text-mono-label text-muted-foreground uppercase"
        >
          {title}
        </span>
      </div>
      <div
        data-slot="terminal-command-row"
        className="grid grid-cols-[minmax(0,1fr)_auto]"
      >
        <TerminalBody
          // The pane is a focus stop only while it actually scrolls, and it is named from the
          // visible title in the usual precedence order — see `terminal-body.tsx` for why the role
          // is `group` rather than `region` and why the outline is pulled inside.
          label={ariaLabel}
          labelledBy={ariaLabelledBy ?? titleId}
        >
          {normalized.map((line, index) => (
            <div
              key={index}
              data-slot="terminal-line"
              className="flex gap-2 whitespace-pre"
            >
              {line.command !== undefined ? (
                <>
                  <span
                    aria-hidden="true"
                    data-slot="terminal-prompt"
                    className="shrink-0 text-brand"
                  >
                    {prompt}
                  </span>
                  <span>{line.command}</span>
                </>
              ) : (
                <span className="text-muted-foreground">{line.output}</span>
              )}
            </div>
          ))}
        </TerminalBody>
        <div
          data-slot="terminal-copy"
          className="flex shrink-0 items-center border-s border-border px-1"
        >
          <CopyButton
            value={copyValue ?? defaultCopyValue}
            copyLabel="Copy command"
            copiedLabel="Copied command"
            className="text-foreground data-[copied]:text-primary data-[copied]:hover:text-primary"
          />
        </div>
      </div>
    </div>
  );
}

// @vegastack terminal@0.7.2 sha256-DDmHUtlBypUeFxmDMtUM5jqZ++fz1E4jrEiy4ehgMMU=

"use client";

import * as React from "react";
import { cn } from "@vegastack/design";
import { useOverflow } from "@/components/ui/use-overflow";

/** Props for `TerminalBody` — the scrollable command pane inside `Terminal`. */
export interface TerminalBodyProps extends React.ComponentProps<"div"> {
  /**
   * Accessible name for the pane. Wins over `labelledBy` — the two are never
   * emitted together, because `aria-labelledby` would silently take precedence
   * in the accessibility tree and the caller's `label` would be dropped.
   * @default undefined
   */
  label?: string;
  /**
   * Id of the element naming the pane — the visible Terminal title, by default.
   * Ignored when `label` is set.
   * @default undefined
   */
  labelledBy?: string;
}

/**
 * `TerminalBody` — the horizontally scrollable command pane, and the only client
 * leaf in the Terminal family.
 *
 * Terminal itself is server-safe (non-negotiable #3) and stays that way: the one
 * thing here that needs a hook — measuring whether the pane actually scrolls — is
 * isolated in this file, exactly as `table-scroll-region.tsx` is for `Table`.
 *
 * The pane takes `tabIndex={0}` **only while it overflows**. A scrollable region
 * that cannot be focused is unreachable without a pointer (axe
 * `scrollable-region-focusable`); an unconditional tab stop on a one-line install
 * snippet is the opposite error — a dead stop on every marketing page that shows
 * one. `useOverflow` settles which of the two applies, live.
 *
 * The NAME and the ROLE are unconditional, and only the tab stop moves. A bare
 * `<div tabindex="0">` maps to `generic`, which prohibits naming, so `aria-label`
 * on it is not reliably exposed; `group` accepts a name and is not a landmark —
 * `region` is, and a docs page with five install snippets would put five
 * landmarks in the rotor for no navigational value. Keeping the named group when
 * the pane happens to fit costs nothing and keeps the announced structure stable
 * across a resize, whereas a role that appears and disappears under the reader
 * as the viewport changes width does not.
 *
 * `scroll-fade-x` masks the element to its own border box, and the Terminal root
 * is `overflow-hidden`, so an outward focus outline is not painted at all — hence
 * `-outline-offset-2`. A border tint is not an option either: `forced-colors:
 * active` replaces border-color outright, which would leave this region with no
 * focus indicator in the forced palette.
 *
 * @example
 * <TerminalBody labelledBy={titleId}>
 *   <pre>pnpm add @vegastack/design</pre>
 * </TerminalBody>
 */
export function TerminalBody({
  className,
  label,
  labelledBy,
  children,
  ...props
}: TerminalBodyProps) {
  const [node, setNode] = React.useState<HTMLDivElement | null>(null);
  const scrollable = useOverflow(node, { axis: "inline" });

  return (
    <div
      {...props}
      ref={setNode}
      // Identity AFTER the spread — consumer props must not overwrite the slot
      // every selector and generated surface keys on.
      data-slot="terminal-body"
      data-scrollable={scrollable ? "" : undefined}
      tabIndex={scrollable ? 0 : undefined}
      role="group"
      aria-label={label}
      // Never emit both: `aria-labelledby` wins in the AT, so a caller passing
      // `aria-label` would otherwise be silently ignored.
      aria-labelledby={label ? undefined : labelledBy}
      className={cn(
        "flex min-w-0 flex-col gap-1.5 overflow-x-auto scroll-fade-x px-4 py-3 font-mono text-code text-foreground focus-visible:-outline-offset-2",
        className,
      )}
    >
      {children}
    </div>
  );
}
